INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(36311, 'Luke 24:36', 'Luke', 24, 36, 'هغوی لا د دې پېښو په هکله خبرې کولې چې ناڅاپه عیسی د هغوی په منځ کې ودرېده او هغوی ته یې وویل: «په تاسو دې سلامتي وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_36.mp3', '', 1761754199, 1761754199),
(36312, 'Luke 24:37', 'Luke', 24, 37, 'هغوی ټکان وخوړ او سخت ووېرېدل، ځکه ګومان یې کاوه چې د مړي ارواح ویني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_37.mp3', '', 1761754199, 1761754199),
(36313, 'Luke 24:38', 'Luke', 24, 38, 'خو عیسی هغوی ته وویل: «ولې دومره وارخطا یئ؟ ستاسو په زړونو کې ولې داسې شکونه پیدا کیږي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_38.mp3', '', 1761754199, 1761754199),
(36314, 'Luke 24:39', 'Luke', 24, 39, 'زما لاسونو او پښو ته وګورئ او وګورئ چې دا زه خپله یم. په ما لاس کېږدئ نو بیا به پوه شئ، ځکه چې ارواح غوښه او هډوکي نه لري او لکه څنګه چې تاسو یې وینئ، زه یې لرم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_39.mp3', '', 1761754199, 1761754199),
(36315, 'Luke 24:40', 'Luke', 24, 40, 'کله چې هغه دا وویل، نو خپل لاسونه او پښې یې هغوی ته وښودلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_40.mp3', '', 1761754199, 1761754199),
(36316, 'Luke 24:41', 'Luke', 24, 41, 'هغوی د ډېرې خوشحالۍ او حیرانتیا له امله نه شو کولای چې بیاهم په دې باور وکړي، نو عیسی د هغوی څخه پوښتنه وکړه: «ایا ستاسو سره دلته د خوړلو دپاره څه شته؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_41.mp3', '', 1761754199, 1761754199),
(36317, 'Luke 24:42', 'Luke', 24, 42, 'هغوی ورته یوه ټوټه کباب شوی ماهي ورکړ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_42.mp3', '', 1761754199, 1761754199),
(36318, 'Luke 24:43', 'Luke', 24, 43, 'نو هغه یې واخیست او د هغوی په مخکې یې وخوړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_43.mp3', '', 1761754199, 1761754199),
(36319, 'Luke 24:44', 'Luke', 24, 44, 'بیا عیسی هغوی ته وویل: «دا زما هغه خبرې دي چې کله زه ستاسو سره وم او تاسو ته به مې ویل چې هغه څه چې د موسی په تورات، د پیغمبرانو په لیکنو او د زبور په کتاب کې زما په هکله لیکل شوي دي، باید رښتیا شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_44.mp3', '', 1761754199, 1761754199),
(36320, 'Luke 24:45', 'Luke', 24, 45, 'بیا یې د هغوی ذهنونه روښانه کړل، ترڅو د خدای په کلام پوه شي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_45.mp3', '', 1761754199, 1761754199),
(36321, 'Luke 24:46', 'Luke', 24, 46, 'او هغوی ته یې وویل: «همدارنګه لیکل شوي دي چې مسیح باید کړاوونه وویني او مړ شي او په درېمه ورځ به بیا راژوندی شي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_46.mp3', '', 1761754199, 1761754199),
(36322, 'Luke 24:47', 'Luke', 24, 47, 'او د هغه په نوم به ټولو قومونو ته دا پیغام ورسول شي چې توبه وباسي او خدای به یې ګناهونه وبخښي او پیل به یې له اورشلیم څخه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_47.mp3', '', 1761754199, 1761754199),
(36323, 'Luke 24:48', 'Luke', 24, 48, 'تاسو د دې ټولو شیانو شاهدان یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_48.mp3', '', 1761754199, 1761754199),
(36324, 'Luke 24:49', 'Luke', 24, 49, 'او ګورئ، هغه څه چې زما پلار یې وعده کړې ده، درلېږم. خو باید تر هغې پورې په دې ښار کې پاتې شئ، ترڅو په تاسو باندې اسماني قوت نازل شي.» اسمان ته د عیسی ختل (مرقوس ۱۶‏:‌۱۹‌‏-‌۲۰ او د رسولانو عملونه ۱‏:‌۹‌‏-‌۱۱)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_49.mp3', '', 1761754199, 1761754199),
(36325, 'Luke 24:50', 'Luke', 24, 50, 'بیا عیسی هغوی د ښار څخه دباندې تر بیت‌عنیا پورې بوتلل، خپل لاسونه یې پورته کړل او هغوی ته یې برکت ورکړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_50.mp3', '', 1761754199, 1761754199),
(36326, 'Luke 24:51', 'Luke', 24, 51, 'او په داسې حال کې چې هغوی ته یې برکت ورکاوه د هغوی څخه بېل شو او اسمان ته پورته یووړل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_51.mp3', '', 1761754199, 1761754199),
(36327, 'Luke 24:52', 'Luke', 24, 52, 'هغوی ورته سجده وکړه او په ډېرې خوشحالۍ سره بېرته اورشلیم ته راستانه شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_52.mp3', '', 1761754199, 1761754199),
(36328, 'Luke 24:53', 'Luke', 24, 53, 'هغوی خپل ټول وخت د خدای په کور کې خدای ته په ثنا ویلو تېر کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke24_verse_53.mp3', '', 1761754199, 1761754199),
(36329, 'Luke 13:1', 'Luke', 13, 1, 'په همدې وخت کې په هغه ځای کې ځینو حاضرینو عیسی د هغو جلیلیانو څخه خبر کړ چې پیلاتوس هغوی خدای ته د قرباني وړاندې کولو په وخت کې وژلي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_1.mp3', '', 1761754199, 1761754199),
(36330, 'Luke 13:2', 'Luke', 13, 2, 'عیسی هغوی ته په ځواب کې وویل: «ایا ګومان کوئ چې دغه جلیلیان د جلیل له نورو ټولو اوسېدونکو څخه ډېر ګناهکاران وو چې په دې ډول ووژل شول؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_2.mp3', '', 1761754199, 1761754199),
(36331, 'Luke 13:3', 'Luke', 13, 3, 'نه، زه تاسو ته وایم که چېرې تاسو توبه ونه باسئ، نو تاسو ټول به د هغوی په شان تباه شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_3.mp3', '', 1761754199, 1761754199),
(36332, 'Luke 13:4', 'Luke', 13, 4, 'یا هغه اتلس تنه چې په سیلوام کې ورباندې برج راوغورځېده او مړه شول، ایا ګومان کوئ چې هغوی د هغو نورو ټولو خلکو څخه چې په اورشلیم کې اوسیږي ډېر ګناهکاران وو؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_4.mp3', '', 1761754199, 1761754199),
(36333, 'Luke 13:5', 'Luke', 13, 5, 'نه، زه تاسو ته وایم که چېرې توبه ونه باسئ، نو تاسو ټول به د هغوی په شان تباه شئ.» د بې‌مېوې انځر د ونې مثال', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_5.mp3', '', 1761754199, 1761754199),
(36334, 'Luke 13:6', 'Luke', 13, 6, 'بیا عیسی هغوی ته دا مثال راوړ: «یو سړي خپل د انګورو په باغ کې د انځر یوه ونه کرلې وه. کله چې راغی چې انځران راټول کړي، هېڅ یې په کې پیدا نه کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_6.mp3', '', 1761754199, 1761754199),
(36335, 'Luke 13:7', 'Luke', 13, 7, 'نو خپل باغوان ته یې وویل: ‹ګوره، درې کاله کیږي چې راځم او په دې ونه کې مېوه لټوم، خو هېڅ مې په کې پیدا نه کړ. دا ونه ووهه. دې ونې ولې هسې ځای نیولی دی؟›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_7.mp3', '', 1761754199, 1761754199),
(36336, 'Luke 13:8', 'Luke', 13, 8, 'خو باغوان ورته ځواب ورکړ: ‹باداره! دا کال یې هم پرېږده، زه به د هغې شاوخوا ځمکه وکینم او سره به ورته واچوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_8.mp3', '', 1761754199, 1761754199),
(36337, 'Luke 13:9', 'Luke', 13, 9, 'که په راتلونکي فصل کې یې مېوه ونیوله نو ډېره ښه به وي، که نه نو بیا کولای شې چې ویې وهې.›» عیسی د سبت په ورځ یوې ښځې ته شفا ورکوي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_9.mp3', '', 1761754199, 1761754199),
(36338, 'Luke 13:10', 'Luke', 13, 10, 'د سبت په یوه ورځ عیسی په کنیسه کې تعلیم ورکاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_10.mp3', '', 1761754199, 1761754199),
(36339, 'Luke 13:11', 'Luke', 13, 11, 'هلته یوه ښځه وه چې اتلس کاله کېدل چې پېریانو نیولې وه او هغه یې کمزورې کړې وه. ملا یې ورته داسې کړوپه کړې وه چې بیخي سمه ودرېدلی نه شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_11.mp3', '', 1761754199, 1761754199),
(36340, 'Luke 13:12', 'Luke', 13, 12, 'کله چې عیسی هغه ښځه ولیدله، نو هغه یې راوغوښتله او ورته ویې ویل: «ای خورې! ته د خپلې ناروغۍ څخه خلاصه شوې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_12.mp3', '', 1761754199, 1761754199),
(36341, 'Luke 13:13', 'Luke', 13, 13, 'بیا یې خپل لاسونه په هغې باندې کېښودل او هغه سمدلاسه نېغه ودرېدله او د خدای ثنا یې وویله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_13.mp3', '', 1761754199, 1761754199),
(36342, 'Luke 13:14', 'Luke', 13, 14, 'خو د کنیسې مشر د عیسی په دې کار چې د سبت په ورځ یې ناروغ ته شفا ورکړې وه، خفه شو او خلکو ته یې وویل: «په هفته کې شپږ ورځې دي چې باید کار وشي، نو په همدې ورځو کې راځئ او شفا مومئ، خو د سبت په ورځ نه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_14.mp3', '', 1761754199, 1761754199),
(36343, 'Luke 13:15', 'Luke', 13, 15, 'خو عیسی هغه ته ځواب ورکړ: «ای منافقانو! ایا تاسو هر یو د سبت په ورځ خپل غویی یا خر د آخور څخه نه ایله کوئ او د اوبو دپاره یې نه بیایئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_15.mp3', '', 1761754199, 1761754199),
(36344, 'Luke 13:16', 'Luke', 13, 16, 'نو دا ښځه د ابراهیم لور ده او اتلس کاله کیږي چې د شیطان په بند کې وه. ایا هغه باید د سبت په ورځ د بند څخه ازاده نه شي؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_16.mp3', '', 1761754199, 1761754199),
(36345, 'Luke 13:17', 'Luke', 13, 17, 'د عیسی په دې خبرو د هغه مخالفین خجالته شول، خو خلک د هغه په دې حیرانوونکي کارونو چې کول یې، خوشحاله شول. د شړشمو د تخم مثال (متي ۱۳‏:‌۳۱‌‏-‌۳۲ او مرقوس ۴‏:‌۳۰‌‏-‌۳۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_17.mp3', '', 1761754199, 1761754199),
(36346, 'Luke 13:18', 'Luke', 13, 18, 'بیا عیسی پوښتنه وکړه: «د خدای پاچاهي د څه شي په شان ده او هغه د څه شي سره پرتله کړم؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_18.mp3', '', 1761754199, 1761754199),
(36347, 'Luke 13:19', 'Luke', 13, 19, 'دا د شړشمو د تخم په شان ده چې یو سړي هغه راواخیست او په خپل پټي کې یې وکرلو. هغه لوی شو او بوټی ترې جوړ شو او مرغان راغلل او د هغه په څانګو یې ځالې جوړې کړې.» د خمیرې مثال (متي ۱۳‏:‌۳۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_19.mp3', '', 1761754199, 1761754199),
(36348, 'Luke 13:20', 'Luke', 13, 20, 'عیسی یوځل بیا پوښتنه وکړه: «د خدای پاچاهي د څه شي سره پرتله کړم؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_20.mp3', '', 1761754199, 1761754199),
(36349, 'Luke 13:21', 'Luke', 13, 21, 'دا د هغې خمیرې په شان ده چې یوه ښځه هغه واخلي او د درې پیمانې اوړو سره یې ګډه کړي، ترڅو هغه ټول خمیره شي.» د تنګې دروازې مثال (متي ۷‏:‌۱۳‌‏-‌۱۴،‌۲۱‌‏-‌۲۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_21.mp3', '', 1761754199, 1761754199),
(36350, 'Luke 13:22', 'Luke', 13, 22, 'عیسی اورشلیم ته روان ؤ او په لاره یې په ښارونو او کلیو کې خلکو ته تعلیم ورکاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_22.mp3', '', 1761754199, 1761754199),
(36351, 'Luke 13:23', 'Luke', 13, 23, 'یو چا ورڅخه پوښتنه وکړه: «استاذه! ایا یوازې لږ خلک به خلاصون ومومي؟» عیسی ځواب ورکړ:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_23.mp3', '', 1761754199, 1761754199),
(36352, 'Luke 13:24', 'Luke', 13, 24, '«زیات کوښښ وکړئ چې له تنګې دروازې څخه وردننه شئ، ځکه زه تاسو ته وایم چې ډېر خلک به د ننوتلو هڅه وکړي، خو وبه نه شي کړای.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_24.mp3', '', 1761754199, 1761754199),
(36353, 'Luke 13:25', 'Luke', 13, 25, 'کله چې یوځل د کور خاوند راپاڅیږي او دروازه بنده کړي، نو تاسو به دباندې پاتې شئ او دروازه به ټکوئ او وایئ به چې ای ښاغلیه! دروازه خلاصه کړه. خو هغه به ځواب درکړي چې زه تاسو نه پېژنم چې له کوم ځای نه راغلي یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_25.mp3', '', 1761754199, 1761754199),
(36354, 'Luke 13:26', 'Luke', 13, 26, 'نو بیا به تاسو وایئ: ‹مونږ تا سره په یو دسترخوان خوړلې او څښلې او تا زمونږ په کوڅو کې تعلیم ورکاوه.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_26.mp3', '', 1761754199, 1761754199),
(36355, 'Luke 13:27', 'Luke', 13, 27, 'خو هغه به بیا درته ووایي: ‹زه تاسو نه پېژنم چې له کوم ځای نه راغلي یئ. ای بدکارانو! زما د مخې نه لېرې شئ.›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_27.mp3', '', 1761754199, 1761754199),
(36356, 'Luke 13:28', 'Luke', 13, 28, 'کله چې تاسو ووینئ چې ابراهیم، اسحاق، یعقوب او ټول پیغمبران د خدای په پاچاهۍ کې دي خو تاسو ورڅخه شړل شوي یئ، نو بیا به ژاړئ او خپل غاښونه به چیچئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_28.mp3', '', 1761754199, 1761754199),
(36357, 'Luke 13:29', 'Luke', 13, 29, 'خلک به د ختیځ او لوېدیځ او شمال او جنوب څخه راشي او د خدای د پاچاهۍ په مېلمستیا کې به کښېني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_29.mp3', '', 1761754199, 1761754199),
(36358, 'Luke 13:30', 'Luke', 13, 30, 'څوک چې اوس وروستي دي، هغوی به اول شي او څوک چې اول وي هغوی به وروستي شي.» د اورشلیم دپاره د عیسی خفګان (متي ۲۳‏:‌۳۷‌‏-‌۳۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_30.mp3', '', 1761754199, 1761754199),
(36359, 'Luke 13:31', 'Luke', 13, 31, 'په هماغه وخت کې یو څو فریسیان عیسی ته راغلل او ورته ویې ویل: «دا ځای پرېږده او کوم بل ځای ته لاړ شه، ځکه چې هیرودیس غواړي تا ووژني.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_31.mp3', '', 1761754199, 1761754199),
(36360, 'Luke 13:32', 'Luke', 13, 32, 'عیسی هغوی ته وویل: «لاړ شئ او هغه ګیدړ ته ووایئ چې زه نن او سبا پېریان وباسم او خلک روغوم او په درېمه ورځ به خپل کار پای ته ورسوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_32.mp3', '', 1761754199, 1761754199),
(36361, 'Luke 13:33', 'Luke', 13, 33, 'په هر حال، زه باید نن او سبا او بل سبا خپل سفر ته دوام ورکړم، ځکه چې دا ناشونې ده چې یو پیغمبر دې د اورشلیم څخه پرته په بل ځای کې ووژل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_33.mp3', '', 1761754199, 1761754199),
(36362, 'Luke 13:34', 'Luke', 13, 34, 'ای اورشلیمه! ای اورشلیمه! ای هغه ښاره چې پیغمبران وژنې او کوم کسان چې د خدای له خوا درلېږل کیږي، هغه سنګساروې. ما څو څو ځلې وغوښتل چې ستا خلک داسې سره راټول کړم لکه چرګه چې خپل بچي د خپلو وزرونو لاندې راټولوي، خو تا ونه غوښتل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_34.mp3', '', 1761754199, 1761754199),
(36363, 'Luke 13:35', 'Luke', 13, 35, 'ګوره، ستاسو کور تاسو ته خالي پرېښودل کیږي. زه تاسو ته وایم چې نور به ما تر هغې ونه وینئ ترڅو هغه وخت راشي چې دا ووایئ: ‹مبارک دی هغه څوک چې د څښتن په نوم راځي.›»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/luke13_verse_35.mp3', '', 1761754199, 1761754199),
(36364, 'John 10:1', 'John', 10, 1, 'په یقین سره زه تاسو ته دا وایم چې هرڅوک چې د پسونو پنډغالي ته د دروازې په لاره نه ورننوځي، بلکې د کومې بلې لارې نه ورننوځي هغه غل او داړه مار دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john10_verse_1.mp3', '', 1761754199, 1761754199),
(36365, 'John 10:2', 'John', 10, 2, 'خو کوم سړی چې په دروازه ورننوځي هغه د پسونو شپون دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john10_verse_2.mp3', '', 1761754199, 1761754199),
(36366, 'John 10:3', 'John', 10, 3, 'څوکیدار هغه ته دروازه خلاصوي او کله چې هغه خپلو پسونو ته نوم اخلي او نارې ورته وهي نو پسونه د هغه اواز پېژني او هغه یې دباندې وباسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john10_verse_3.mp3', '', 1761754199, 1761754199),
(36367, 'John 10:4', 'John', 10, 4, 'کله چې هغه خپل ټول پسونه وباسي نو شپون یې مخکې روان وي او پسونه ورپسې وي، ځکه چې د هغه اواز پېژني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john10_verse_4.mp3', '', 1761754199, 1761754199),
(36368, 'John 10:5', 'John', 10, 5, 'هغوی د پردي سړي پسې نه ځي بلکې د هغه نه تښتي، ځکه چې هغوی د پردي سړي اواز نه پېژني.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john10_verse_5.mp3', '', 1761754199, 1761754199),
(36369, 'John 10:6', 'John', 10, 6, 'عیسی هغوی ته دا مثال راوړ، خو هغوی په دې پوه نه شول چې د هغه مقصد څه دی. عیسی نېک شپون دی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john10_verse_6.mp3', '', 1761754199, 1761754199),
(36370, 'John 10:7', 'John', 10, 7, 'عیسی یوځل بیا هغوی ته وویل: «په یقین سره زه تاسو ته دا وایم چې زه د پسونو دپاره د دروازې په شان یم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john10_verse_7.mp3', '', 1761754199, 1761754199),
(36371, 'John 10:8', 'John', 10, 8, 'هغه ټول نور چې زما نه مخکې راغلي وو، غله او داړه ماران وو او پسونو د هغوی اواز ته غوږ نه دی نیولی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john10_verse_8.mp3', '', 1761754199, 1761754199),
(36372, 'John 10:9', 'John', 10, 9, 'زه د دروازې په شان یم. هرڅوک چې زما له لارې ننوځي نو هغوی به وژغورل شي. هغوی به ځي او راځي او ښه څړځای به پیدا کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john10_verse_9.mp3', '', 1761754199, 1761754199),
(36373, 'John 10:10', 'John', 10, 10, 'غل یوازې د غلا، قتل او بربادۍ دپاره راځي. زه د دې دپاره راغلی یم چې زما پسونه ژوندون ومومي او د هغوی په ژوند کې هرڅه پرېمانه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john10_verse_10.mp3', '', 1761754199, 1761754199),
