(36376, 'John 10:13', 'John', 10, 13, 'هغه تښتي، ځکه چې هغه مزدور دی او د پسونو پروا نه لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john10_verse_13.mp3', '', 1761754199, 1761754199),
