(36406, 'Romans 16:1', 'Romans', 16, 1, 'زه تاسو ته زمونږ خور فیبي چې د کينخریه د کلیسا خادمه ده، درپېژنم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_1.mp3', '', 1761754199, 1761754199),
(36407, 'Romans 16:2', 'Romans', 16, 2, 'تاسو هغې ته د عیسی مسیح په نوم لکه څنګه چې د خدای د خلکو سره مناسب دي، هرکلی ووایئ او هر شي ته چې اړتیا ولري ورسره مرسته وکړئ، ځکه چې هغې د ډېرو سره مرسته کړې ده او زما سره یې هم کړې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_2.mp3', '', 1761754199, 1761754199),
(36408, 'Romans 16:3', 'Romans', 16, 3, 'پریسکیلا او د هغې مېړه اکیلا ته چې د عیسی مسیح په خدمت کې زما ملګري دي، سلام ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_3.mp3', '', 1761754199, 1761754199),
(36409, 'Romans 16:4', 'Romans', 16, 4, 'هغوی خپل ځانونه زما په خاطر په خطر کې واچول، د هغوی څخه یوازې زه نه بلکې د غیریهودیانو ټولې کلیساګانې شکرګزاري کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_4.mp3', '', 1761754199, 1761754199),
(36410, 'Romans 16:5', 'Romans', 16, 5, 'د هغې کلیسا غړو ته هم سلامونه ووایئ چې د هغوی په کور کې سره راټولیږي. زما ګران دوست اپنتوس ته چې د اسیا په ولایت کې لومړنی کس ؤ چې په مسیح باندې یې ایمان راوړ، هم سلامونه ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans16_verse_5.mp3', '', 1761754199, 1761754199);